using System;
using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CodexOfBurdensOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/CodexOfBurdensOmenData")]
public class CodexOfBurdensOmenData : OmenData
{
	[Header("CodexOfBurdensOmenData Omen")]
	[SerializeField]
	private int additionalDieAmount = 1;

	[SerializeField]
	private DrawAdditionalDieOmenData drawAdditionalDieOmenData;

	[SerializeField]
	private PlayerCurrentRunes playerCurrentRunes;

	[SerializeField]
	private OmenDescriptionIDReferences omenDescriptionIDReferences;

	[NonSerialized]
	private OmenInstance omenInstance;

	[NonSerialized]
	private Func<int> drawAdditionalDieOmenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		playerCurrentRunes.SetCodexOfBurdenOmenAction(value: true, delegate
		{
			ToggleAlreadyUsed(toggle: true);
			omenInstance.EnqueueOmenFeedbackAndPlay();
			playerCurrentRunes.DisableAllRunes();
		});
		drawAdditionalDieOmenData.InitializeNoStartOfBattle(omenInstance, additionalDieAmount, ref drawAdditionalDieOmenAction);
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartStartTurnOmens.Add(omenInstance);
		this.omenInstance = omenInstance;
	}

	public override void OmenRemoved()
	{
		playerCurrentRunes.SetCodexOfBurdenOmenAction(value: false, null);
		drawAdditionalDieOmenData.OmenRemovedNoStartOfBattle(ref drawAdditionalDieOmenAction);
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartStartTurnOmens.Remove(omenInstance);
		omenInstance = null;
	}

	public override string OmenConvertedDescription()
	{
		string text = base.OmenConvertedDescription();
		return drawAdditionalDieOmenData.GetDrawAdditionalDieDescription(additionalDieAmount) + "\n" + text;
	}
}
